import"./chunk-2NFLSA4Y.js";var r={heatEngine:{theory:{concept:"[[A heat engine is a device that converts part of the heat taken from a hot reservoir into mechanical work and gives the rest to a cold reservoir.]] It works in a repeating cycle, so the work per cycle is W = Q\u2095 \u2212 Q\u{1D68C} and the efficiency is \u03B7 = W / Q\u2095. By the second law of thermodynamics no engine working between the temperatures T\u2095 and T\u{1D68C} can be more efficient than the ideal Carnot engine, \u03B7 = 1 \u2212 T\u{1D68C} / T\u2095 (temperatures in kelvins). Real engines also lose energy to friction and heat leaks, so their efficiency is lower."},param:{hot:"Hot reservoir",cold:"Cold reservoir",amount:"Amount of gas",ratio:"Isothermal expansion ratio",period:"Animation cycle duration",volume:"Minimum gas volume",timeStep:"Time step"},hint:{hot:"A hotter source increases the maximum efficiency.",cold:"A colder sink allows more of the supplied heat to become work.",ratio:"Ratio of volumes at the end and start of hot isothermal expansion.",period:"Changes playback speed only, not work per cycle or physical power."},preset:{warm:"400 K",hot:"800 K",cold:"200 K",room:"300 K"},measure:{efficiency:"Carnot efficiency",heatIn:"Heat received per cycle",heatOut:"Heat rejected per cycle",cycleWork:"Net work per cycle",temperature:"Gas temperature",cycles:"Completed cycles",volume:"Gas volume",pressure:"Gas pressure",heat:"Cumulative net heat into gas",work:"Cumulative work by gas",deltaU:"Internal energy change",balance:"First-law residual",time:"Playback time"},graph:{pv:"Carnot pressure\u2013volume cycle",energy:"Heat, work and internal energy"},view:{transfers:"Energy transfer arrows",stage0:"1 \xB7 Isothermal expansion",stage1:"2 \xB7 Adiabatic expansion",stage2:"3 \xB7 Isothermal compression",stage3:"4 \xB7 Adiabatic compression",insulated:"Insulated \xB7 Q = 0",heatIn:"Heat enters from the hot reservoir",heatOut:"Heat leaves for the cold reservoir",workBy:"Gas does work \u2191",workOn:"Work on gas \u2193",schematic:"Schematic \xB7 not to scale \xB7 playback time"},section:{cycle:{title:"Four stages",text:"The gas expands at the hot temperature, then expands without heat exchange and cools. It is compressed at the cold temperature, then compressed without heat exchange until it returns to its original state. Only the relevant reservoir is connected during each isotherm; both are disconnected during adiabats."},efficiency:{title:"Temperature limits efficiency",text:"[[Carnot efficiency depends on the reservoir temperatures in kelvin.]] A larger temperature difference helps. Some heat must leave for the cold reservoir: an engine between positive temperatures cannot convert all heat into work."},work:{title:"Net work of a cycle",text:"[[Expansion produces work and compression consumes work.]] The difference is the net output, equal to the area enclosed by the pressure\u2013volume cycle. Internal energy returns to its initial value after every cycle."}},formula:{energy:"Energy balance and engine efficiency",efficiency:"Maximum reversible efficiency; temperatures in kelvin",gas:"Monatomic ideal gas",heat:"Heat exchanged on the isotherms; r = V\u2082/V\u2081",adiabatic:"Reversible insulated branches",entropy:"Zero total reservoir entropy change for a reversible cycle"},variable:{constant:"Gas constant (8.314)"},assumption:{gas:"Closed monatomic ideal gas with constant heat capacities: \u03B3 = 5/3. Only pressure-volume work is included.",reversible:"All branches are reversible and quasistatic. The piston has no friction or inertia; there are no heat leaks.",reservoirs:"Reservoir temperatures stay fixed. Heat exchange occurs only on the isotherms, with the corresponding reservoir.",playback:"The animation traverses equilibrium states in a chosen playback time. This ideal reversible cycle does not predict finite physical power or real cycle duration.",scale:"Cylinder, piston displacement, arrows and reservoirs are schematic and not to scale."},challenge:{efficient:{title:"Improve efficiency",description:"Reach at least 60% Carnot efficiency with positive work output.",hint:"Try a hot reservoir at 800 K and a cold one at 300 K."},close:{title:"Most heat leaves",description:"Keep efficiency at or below 25% so at least three quarters of the input heat reaches the cold reservoir.",hint:"Bring the temperatures closer: try 400 K and 300 K."},cycle:{title:"Complete a cycle",description:"Run one full cycle with positive work and conserved energy.",hint:"Let the animation finish all four stages."},work:{title:"More work per cycle",description:"Obtain at least 2000 J of net work per cycle.",hint:"Increase gas amount, expansion ratio and the temperature difference."},conservation:{title:"Check repeated cycles",description:"Complete two cycles and verify both cycle energy balance and the first law.",hint:"Compare received heat, rejected heat and net work, then inspect the first-law residual."}}}},a={sim:r};export{a as default,r as sim};
